"""Renders positioned pages onto a ReportLab canvas."""
from __future__ import annotations

import hashlib
import io
import math
from typing import List, Optional

from reportlab.lib.colors import Color
from reportlab.pdfgen import canvas as rl_canvas

from ..layout import (DestOp, ImageOp, LineOp, LinkOp, OutlineOp, Page,
                      RectOp, TextOp)

ITALIC_SKEW = math.tan(math.radians(12.0))


def _rgb(hex_color: Optional[str]) -> Color:
    value = (hex_color or '000000').lstrip('#')
    if len(value) == 3:
        value = ''.join(ch * 2 for ch in value)
    try:
        r = int(value[0:2], 16) / 255.0
        g = int(value[2:4], 16) / 255.0
        b = int(value[4:6], 16) / 255.0
    except (ValueError, IndexError):
        return Color(0, 0, 0)
    return Color(r, g, b)


class Renderer:
    def __init__(self, pages: List[Page], document=None, options=None):
        self.pages = pages
        self.doc = document
        self.options = options or {}
        self.warnings: list = []
        self._image_cache: dict = {}

    def write(self, target) -> None:
        pagesize = (self.pages[0].width, self.pages[0].height) if self.pages else (612, 792)
        canvas = rl_canvas.Canvas(target, pagesize=pagesize,
                                  pageCompression=1 if self.options.get(
                                      'compress', True) else 0)
        self._set_metadata(canvas)
        outline_stack: list = []
        for index, page in enumerate(self.pages):
            canvas.setPageSize((page.width, page.height))
            self._draw_page(canvas, page, outline_stack)
            canvas.showPage()
        if not self.pages:
            canvas.showPage()
        canvas.save()

    def _set_metadata(self, canvas):
        props = (self.doc.properties if self.doc else {}) or {}
        title = self.options.get('title') or props.get('title')
        author = self.options.get('author') or props.get('creator')
        subject = props.get('subject')
        keywords = props.get('keywords')
        if title:
            canvas.setTitle(title)
        if author:
            canvas.setAuthor(author)
        if subject:
            canvas.setSubject(subject)
        if keywords:
            canvas.setKeywords(keywords)
        canvas.setCreator('Word2PDF (pure Python)')

    # ------------------------------------------------------------------
    def _draw_page(self, canvas, page: Page, outline_stack):
        height = page.height
        for op in page.ops:
            if isinstance(op, RectOp):
                if op.fill:
                    canvas.setFillColor(_rgb(op.fill))
                    canvas.rect(op.x, height - op.y - op.h, op.w, op.h,
                                stroke=0, fill=1)
                if op.stroke and op.line_width:
                    canvas.setStrokeColor(_rgb(op.stroke))
                    canvas.setLineWidth(op.line_width)
                    canvas.rect(op.x, height - op.y - op.h, op.w, op.h,
                                stroke=1, fill=0)
            elif isinstance(op, LineOp):
                canvas.saveState()
                canvas.setStrokeColor(_rgb(op.color))
                canvas.setLineWidth(op.width)
                if op.dash:
                    canvas.setDash([d * max(1.0, op.width) for d in op.dash])
                canvas.line(op.x1, height - op.y1, op.x2, height - op.y2)
                canvas.restoreState()
            elif isinstance(op, TextOp):
                self._draw_text(canvas, op, height)
            elif isinstance(op, ImageOp):
                self._draw_image(canvas, op, height)
            elif isinstance(op, LinkOp):
                rect = (op.x, height - op.y - op.h, op.x + op.w, height - op.y)
                if op.url:
                    canvas.linkURL(op.url, rect, relative=0, thickness=0)
                elif op.anchor:
                    canvas.linkRect('', _dest(op.anchor), rect, relative=0,
                                    thickness=0)
            elif isinstance(op, DestOp):
                canvas.bookmarkHorizontal(_dest(op.name), 0, height - op.y)
            elif isinstance(op, OutlineOp):
                self._add_outline(canvas, op, height, outline_stack)

    def _draw_text(self, canvas, op: TextOp, page_height: float):
        y = page_height - op.y
        canvas.saveState()
        canvas.setFillColor(_rgb(op.color))
        try:
            canvas.setFont(op.font, op.size)
        except KeyError:
            canvas.setFont('Helvetica', op.size)
        if op.faux_bold:
            canvas.setStrokeColor(_rgb(op.color))
            canvas.setLineWidth(max(0.1, op.size * 0.025))
        transformed = op.faux_italic or op.scale != 100.0
        if transformed:
            canvas.translate(op.x, y)
            scale = (op.scale or 100.0) / 100.0
            canvas.transform(scale, 0, ITALIC_SKEW if op.faux_italic else 0, 1, 0, 0)
            text = canvas.beginText(0, 0)
        else:
            text = canvas.beginText(op.x, y)
        text.setFont(op.font if _has_font(canvas, op.font) else 'Helvetica', op.size)
        if op.char_space:
            text.setCharSpace(op.char_space)
        if op.faux_bold:
            text.setTextRenderMode(2)
        text.textOut(op.text)
        canvas.drawText(text)
        canvas.restoreState()

    def _draw_image(self, canvas, op: ImageOp, page_height: float):
        reader = self._image_reader(op)
        if reader is None:
            return
        y = page_height - op.y - op.h
        canvas.saveState()
        try:
            if op.rotation:
                canvas.translate(op.x + op.w / 2.0, y + op.h / 2.0)
                canvas.rotate(-op.rotation)
                canvas.drawImage(reader, -op.w / 2.0, -op.h / 2.0, width=op.w,
                                 height=op.h, mask='auto')
            else:
                canvas.drawImage(reader, op.x, y, width=op.w, height=op.h,
                                 mask='auto')
        except Exception as exc:                       # unsupported image data
            self.warnings.append('could not draw image: %s' % exc)
        finally:
            canvas.restoreState()

    def _image_reader(self, op: ImageOp):
        data = op.data
        if not data:
            return None
        # Key on the content, not the object: a logo that appears on every page
        # must be embedded once, not once per page.
        key = (hashlib.sha1(data).hexdigest(), op.crop)
        cached = self._image_cache.get(key)
        if cached is not None:
            return cached
        fmt = (op.fmt or '').lower()
        if fmt in ('emf', 'wmf'):
            self.warnings.append('EMF/WMF images cannot be rendered')
            return None
        reader = None
        try:
            from reportlab.lib.utils import ImageReader
            stream = io.BytesIO(data)
            if op.crop:
                stream = self._crop(data, op.crop) or stream
            recompressed = self._recompress(stream.getvalue(), op)
            if recompressed is not None:
                stream = recompressed
            reader = ImageReader(stream)
            reader.getSize()
        except Exception:
            reader = self._via_pillow(data, op.crop)
        self._image_cache[key] = reader
        return reader

    def _recompress(self, data: bytes, op: ImageOp):
        """Optionally downsample and JPEG-encode, the way Word's export does.

        Off by default: the image goes into the PDF exactly as the document
        stored it unless the caller asks for smaller files.
        """
        quality = self.options.get('image_quality')
        max_dpi = self.options.get('image_max_dpi')
        if not quality and not max_dpi:
            return None
        try:
            from PIL import Image
            with Image.open(io.BytesIO(data)) as img:
                img.load()
                width, height = img.size
                has_alpha = img.mode in ('RGBA', 'LA', 'P') and (
                    'transparency' in img.info or img.mode != 'P')
                if max_dpi and op.w > 0 and op.h > 0:
                    target_w = int(round(op.w / 72.0 * max_dpi))
                    target_h = int(round(op.h / 72.0 * max_dpi))
                    if target_w and target_h and (width > target_w or height > target_h):
                        img = img.resize((max(1, target_w), max(1, target_h)),
                                         Image.LANCZOS)
                out = io.BytesIO()
                if quality and not has_alpha:
                    img.convert('RGB').save(out, format='JPEG',
                                            quality=int(quality), optimize=True)
                else:
                    img.save(out, format='PNG', optimize=True)
                out.seek(0)
            return out if out.getbuffer().nbytes < len(data) else None
        except Exception:
            return None

    @staticmethod
    def _crop(data: bytes, crop):
        try:
            from PIL import Image
            with Image.open(io.BytesIO(data)) as img:
                width, height = img.size
                left, top, right, bottom = crop
                box = (int(width * left), int(height * top),
                       int(width * (1 - right)), int(height * (1 - bottom)))
                if box[2] <= box[0] or box[3] <= box[1]:
                    return None
                out = io.BytesIO()
                cropped = img.crop(box)
                if cropped.mode not in ('RGB', 'RGBA', 'L'):
                    cropped = cropped.convert('RGBA')
                cropped.save(out, format='PNG')
                out.seek(0)
                return out
        except Exception:
            return None

    def _via_pillow(self, data: bytes, crop):
        try:
            from PIL import Image
            from reportlab.lib.utils import ImageReader
            with Image.open(io.BytesIO(data)) as img:
                img.load()
                converted = img.convert('RGBA') if img.mode not in (
                    'RGB', 'RGBA', 'L') else img.copy()
            out = io.BytesIO()
            converted.save(out, format='PNG')
            out.seek(0)
            return ImageReader(out)
        except Exception as exc:
            self.warnings.append('unsupported image (%s)' % exc)
            return None

    def _add_outline(self, canvas, op: OutlineOp, page_height: float, stack):
        level = max(0, op.level)
        while len(stack) > level:
            stack.pop()
        while len(stack) < level:
            stack.append(None)
        key = 'outline-%d-%d' % (len(stack), id(op) % 100000)
        canvas.bookmarkHorizontal(key, 0, page_height - op.y)
        try:
            canvas.addOutlineEntry(op.title[:120], key, level=len(stack), closed=False)
        except Exception:
            return
        stack.append(key)


def _has_font(canvas, name: str) -> bool:
    try:
        from reportlab.pdfbase import pdfmetrics
        pdfmetrics.getFont(name)
        return True
    except Exception:
        return False


def _dest(name: str) -> str:
    return 'anchor_' + ''.join(ch if ch.isalnum() else '_' for ch in (name or ''))
